#!/usr/bin/env python3
import argparse
import hashlib
from pathlib import Path

SUBJECT = b"Build time autogenerated kernel key"
BUILD_ID_NOTE_PREFIX = (
    (4).to_bytes(4, "little")
    + (20).to_bytes(4, "little")
    + (3).to_bytes(4, "little")
    + b"GNU\0"
)

def parse_int(value: str) -> int:
    return int(value, 0)

def main() -> int:
    ap = argparse.ArgumentParser(
        description=(
            "Verify a pandora OS4 Full Parity Image against the LKG while "
            "normalizing the autogenerated module-signing certificate and "
            "top-level GNU build-id."
        )
    )
    ap.add_argument("image")
    ap.add_argument("--expected-size", required=True, type=parse_int)
    ap.add_argument("--build-id-payload-offset", required=True, type=parse_int)
    ap.add_argument("--cert-offset", required=True, type=parse_int)
    ap.add_argument("--cert-length", required=True, type=parse_int)
    ap.add_argument("--expected-normalized-sha256", required=True)
    args = ap.parse_args()

    path = Path(args.image)
    data = path.read_bytes()
    if len(data) != args.expected_size:
        raise SystemExit(f"Image size mismatch: {len(data)} != {args.expected_size}")

    bid = args.build_id_payload_offset
    if bid < 16 or bid + 20 > len(data):
        raise SystemExit("build-id payload offset out of range")
    if data[bid - 16:bid] != BUILD_ID_NOTE_PREFIX:
        raise SystemExit(
            f"GNU build-id note header mismatch at 0x{bid-16:x}: "
            f"{data[bid-16:bid].hex()}"
        )

    cert_off = args.cert_offset
    cert_len = args.cert_length
    if cert_off < 0 or cert_off + cert_len > len(data):
        raise SystemExit("certificate region out of range")
    cert = data[cert_off:cert_off + cert_len]
    if len(cert) < 4 or cert[:2] != b"\x30\x82":
        raise SystemExit("expected DER X.509 certificate header not found")
    der_len = int.from_bytes(cert[2:4], "big") + 4
    if der_len != cert_len:
        raise SystemExit(f"certificate DER length mismatch: {der_len} != {cert_len}")
    if SUBJECT not in cert:
        raise SystemExit("autogenerated kernel-key subject not found in certificate region")

    normalized = bytearray(data)
    normalized[bid:bid + 20] = b"\0" * 20
    normalized[cert_off:cert_off + cert_len] = b"\0" * cert_len

    raw_sha = hashlib.sha256(data).hexdigest()
    cert_sha = hashlib.sha256(cert).hexdigest()
    build_id = data[bid:bid + 20].hex()
    norm_sha = hashlib.sha256(normalized).hexdigest()

    print(f"IMAGE_SIZE={len(data)}")
    print(f"IMAGE_SHA256={raw_sha}")
    print(f"GNU_BUILD_ID={build_id}")
    print(f"MODULE_SIGNING_CERT_SHA256={cert_sha}")
    print(f"MODULE_SIGNING_CERT_OFFSET=0x{cert_off:x}")
    print(f"MODULE_SIGNING_CERT_LENGTH={cert_len}")
    print(f"NORMALIZED_IMAGE_SHA256={norm_sha}")

    expected = args.expected_normalized_sha256.lower()
    if norm_sha != expected:
        raise SystemExit(f"normalized Image mismatch: {norm_sha} != {expected}")

    print("LKG_NORMALIZED_IMAGE_EQUIVALENCE=PASS")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
